-- submissions/close
-- Moves a pending submission to its final state. Does nothing if it is no longer pending.
--
-- Parameters, with the example values used to render this file:
--   $1 = "approved"
--   $2 = "0199c8a0-0000-7000-8000-00000000000a"
--   $3 = "pending"
--
-- Generated by `pnpm db:queries` from lib/db/queries/submissions.ts. Do not edit by hand.

update "submissions"
set "status" = $1, "updated_at" = now()
where ("submissions"."id" = $2
  and "submissions"."status" = $3)
returning "id";
